mapper.select:
SELECT id, message_id, employee_id, reaction, created_at, delete_flag
FROM message_reactions
WHERE message_id = #{messageId}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
ORDER BY created_at

SELECT id, message_id, employee_id, reaction, created_at, delete_flag
FROM message_reactions
WHERE message_id = #{messageId}
  AND employee_id = #{employeeId}
  AND reaction = #{reaction}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

mapper.delete:
DELETE FROM message_reactions
WHERE message_id = #{messageId}
  AND employee_id = #{employeeId}
  AND reaction = #{reaction}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM message_reactions
    WHERE message_id = #{messageId}
      AND employee_id = #{employeeId}
      AND reaction = #{reaction}
      AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
)
